'use client';

import { FormEvent, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Feedback from '@/components/Feedback';
import ProtectedPage from '@/components/ProtectedPage';
import { getUserUuid } from '@/lib/auth';
import { inventoryApi } from '@/lib/inventory';
import type { SKU, Warehouse } from '@/lib/types';

export default function InboundPage() {
  const router = useRouter();
  const [products, setProducts] = useState<SKU[]>([]);
  const [skuId, setSkuId] = useState('');
  const [quantity, setQuantity] = useState('');
  const [reference, setReference] = useState('');
  const [warehouse, setWarehouse] = useState<Warehouse>('LA');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    inventoryApi.listSKUs().then((items) => {
      setProducts(items);
      const requestedId = new URLSearchParams(window.location.search).get('sku_id');
      if (requestedId && items.some((item) => item.id === Number(requestedId))) setSkuId(requestedId);
    }).catch((reason: unknown) => setError(reason instanceof Error ? reason.message : 'No se pudieron cargar los SKUs.'));
  }, []);

  const selected = products.find((item) => item.id === Number(skuId));
  useEffect(() => { if (selected) setWarehouse(selected.warehouse); }, [selected]);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setError(''); setSuccess('');
    if (!selected) { setError('Selecciona un SKU válido.'); return; }
    if (!getUserUuid()) { setError('Falta el UUID del operario. Cierra sesión y configúralo de nuevo.'); return; }
    setBusy(true);
    try {
      await inventoryApi.createInbound({ sku_id: selected.id, quantity: Number(quantity), reference: reference.trim(), warehouse, user_uuid: getUserUuid() });
      setSuccess('Entrada registrada correctamente.'); setQuantity(''); setReference('');
      router.refresh();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'No se pudo registrar la entrada.'); }
    finally { setBusy(false); }
  }

  return <ProtectedPage><div className="max-w-2xl"><p className="text-sm font-semibold uppercase tracking-wider text-blue-700">Recepción</p><h1 className="mt-1 text-3xl font-bold">Registrar entrada de stock</h1><p className="mt-2 text-slate-600">Registra la mercancía recibida en el almacén indicado.</p>
    <form onSubmit={submit} className="mt-6 space-y-5 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">
      <label className="block text-sm font-medium">Producto / SKU<select required value={skuId} onChange={(event) => setSkuId(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5"><option value="">Seleccionar producto…</option>{products.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.sku} · {item.warehouse}</option>)}</select></label>
      <label className="block text-sm font-medium">Cantidad recibida<input required min="1" type="number" value={quantity} onChange={(event) => setQuantity(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2.5" /></label>
      <label className="block text-sm font-medium">Referencia de recepción<input required value={reference} onChange={(event) => setReference(event.target.value)} className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2.5" placeholder="PO-2024-0098" /></label>
      <label className="block text-sm font-medium">Almacén<select value={warehouse} onChange={(event) => setWarehouse(event.target.value as Warehouse)} className="mt-1 w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5"><option value="LA">LA — Los Ángeles</option><option value="ZGZ">ZGZ — Zaragoza</option></select></label>
      {error && <Feedback kind="error">{error}</Feedback>}{success && <Feedback kind="success">{success}</Feedback>}
      <button disabled={busy || products.length === 0} className="rounded-lg bg-blue-700 px-5 py-3 font-semibold text-white hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-50">{busy ? 'Guardando…' : 'Registrar entrada'}</button>
    </form>
  </div></ProtectedPage>;
}
